#include <stdio.h>

int main() {
    int s[4][2] = {
        {1234, 56},
        {1212, 33},
        {1434, 80},
        {1312, 78}
    };

    int i;
    for (i = 0; i < 4; i++) {
        printf("\nAddress of %dth 1-D array = %p", i, (void*)s[i]);
    }

    return 0;
}
```

